H=W=18
seven={(4,4),(4,5),(5,4),(5,5),(6,5),(6,9),(7,5),(7,7),(7,8),(7,9),(7,10),(7,11),(8,5),(8,9),(8,10), *[(9,c) for c in range(4,11)],(10,4),(10,5),(10,9),(10,10),(10,11),(10,12),(10,13),(11,11),(11,12)}
